import type postgres from "postgres";
import { MeshDatabase } from "../../src/storage/database.js";

/** Populate an empty CI schema from the coordinator's canonical local DDL. */
export async function createCoordinatorPostgresFixture(sql: postgres.Sql, schema: string): Promise<void> {
  if (!/^handoff_[a-f0-9]+$/.test(schema)) throw new Error("Invalid disposable handoff schema");
  const local = await MeshDatabase.open(":memory:");
  try {
    const catalog = await local.raw.prepare(`
      SELECT entry.name, entry.sql FROM sqlite_schema AS entry
      JOIN pragma_table_list AS tables ON tables.name = entry.tbl_name
      WHERE tables.schema = 'main' AND tables.type = 'table'
        AND entry.type IN ('table', 'index') AND entry.sql IS NOT NULL
        AND entry.name NOT LIKE 'sqlite_%'
      ORDER BY CASE entry.type WHEN 'table' THEN 0 ELSE 1 END, entry.rowid`).all();
    const version = await local.raw.prepare("SELECT version FROM schema_meta").get();
    await sql.begin(async (tx) => {
      await tx.unsafe(`CREATE SCHEMA ${schema}; SET LOCAL search_path TO ${schema}, pg_catalog`);
      const installed = new Set<string>();
      const remaining = [...catalog];
      while (remaining.length) {
        const index = remaining.findIndex(entry => {
          if (typeof entry.sql !== "string") throw new Error("Missing fixture DDL");
          return Array.from(entry.sql.matchAll(/\bREFERENCES\s+"?(\w+)"?/gi))
            .every(([, table]) => table === entry.name || installed.has(table!));
        });
        if (index < 0) throw new Error("Unresolved fixture table dependency");
        const [entry] = remaining.splice(index, 1);
        if (typeof entry?.sql !== "string" || typeof entry.name !== "string") throw new Error("Invalid fixture DDL");
        const ddl = entry.sql
          .replace(/\bINTEGER PRIMARY KEY AUTOINCREMENT\b/gi, "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY")
          .replace(/\bINTEGER\b/gi, "BIGINT")
          .replace(/\bBLOB\b/gi, "BYTEA");
        try { await tx.unsafe(ddl); }
        catch (error) { throw new Error(`Fixture DDL failed for ${entry.name}`, { cause: error }); }
        installed.add(entry.name);
      }
      await tx`INSERT INTO schema_meta (version) VALUES (${Number(version?.version)})`;
    });
  } finally {
    await local.close();
  }
}
